INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Drucker Funktion, Einsatz, Varianten > Impactdrucker (Schlagdrucker)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Impactdrucker unabhängig vom Papiertyp ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Benötigen spezielles Durchschlagpapier"}, {"text": "Ja", "correct": false, "because": "Papierart ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl eines Impactdruckers immer die Lautstärkeanforderungen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Schlagdrucker sind oft laut"}, {"text": "Nein", "correct": false, "because": "Lautstärke ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Druckgeschwindigkeit eines Impactdruckers für alle Anwendungen entscheidend?', 2, '[{"text": "Nein", "correct": true, "because": "Wichtiger bei hohem Volumen, weniger bei Qualität"}, {"text": "Ja", "correct": false, "because": "Geschwindigkeit nicht immer primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Impactdrucker ohne Rücksicht auf die Verbrauchsmaterialien ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Farbbänder oder Nadeln müssen kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Verbrauchsmaterialien sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Impactdrucker immer langsamer als moderne Laserdrucker?', 2, '[{"text": "Ja", "correct": true, "because": "Mechanische Technik ist langsamer"}, {"text": "Nein", "correct": false, "because": "Geschwindigkeit ist typischerweise geringer"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl eines Impactdruckers am wichtigsten?', 3, '[{"text": "Anwendungsanforderungen", "correct": true, "because": "Bestimmen Papier und Einsatz"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie wird bei Impactdruckern am häufigsten verwendet?', 2, '[{"text": "Nadelmatrix", "correct": true, "because": "Standard für Schlagdrucker"}, {"text": "Daisywheel", "correct": false, "because": "Älter und seltener"}, {"text": "Laser", "correct": false, "because": "Nicht Impact"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verbrauchsmaterial ist für Impactdrucker essenziell?', 2, '[{"text": "Farbband", "correct": true, "because": "Überträgt Tinte aufs Papier"}, {"text": "Toner", "correct": false, "because": "Für Laserdrucker"}, {"text": "Tintenpatrone", "correct": false, "because": "Für Tintenstrahldrucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung ist typisch für Impactdrucker?', 3, '[{"text": "Durchschlagdruck", "correct": true, "because": "Für mehrlagiges Papier geeignet"}, {"text": "Fotodruck", "correct": false, "because": "Falsche Technologie"}, {"text": "Etikettendruck", "correct": false, "because": "Andere Drucker besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von Impactdruckern?', 2, '[{"text": "Durchschlagfähigkeit", "correct": true, "because": "Mehrere Kopien gleichzeitig"}, {"text": "Hohe Druckqualität", "correct": false, "because": "Eher gering"}, {"text": "Schnelle Druckzeit", "correct": false, "because": "Langsamer als Laser"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl eines Impactdruckers?', 4, '[{"text": "Papierkompatibilität", "correct": true, "because": "Durchschlagpapier nötig"}, {"text": "Lautstärke", "correct": true, "because": "Lärm kann störend sein"}, {"text": "Verbrauchsmaterialien", "correct": true, "because": "Farbbänder erforderlich"}, {"text": "Gewicht des Druckers", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Impactdrucker?', 3, '[{"text": "Durchschlagfähigkeit", "correct": true, "because": "Mehrere Kopien"}, {"text": "Geringe Betriebskosten", "correct": true, "because": "Einfache Materialien"}, {"text": "Robustheit", "correct": true, "because": "Langlebige Mechanik"}, {"text": "Hohe Auflösung", "correct": false, "because": "Eher gering"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben Impactdrucker?', 3, '[{"text": "Hohe Lautstärke", "correct": true, "because": "Mechanischer Betrieb"}, {"text": "Langsame Druckgeschwindigkeit", "correct": true, "because": "Im Vergleich zu Laser"}, {"text": "Geringe Druckqualität", "correct": true, "because": "Nur Text geeignet"}, {"text": "Hohe Anschaffungskosten", "correct": false, "because": "Eher günstig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen können Impactdrucker unterstützen?', 4, '[{"text": "USB", "correct": true, "because": "Moderne Modelle"}, {"text": "Parallelport", "correct": true, "because": "Ältere Standards"}, {"text": "Serial", "correct": true, "because": "Frühere Verbindung"}, {"text": "HDMI", "correct": false, "because": "Für Video, nicht Drucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen sind typisch für Impactdrucker?', 3, '[{"text": "Rechnungsdruck", "correct": true, "because": "Durchschlag für Kopien"}, {"text": "Logistikdokumente", "correct": true, "because": "Mehrlagiges Papier"}, {"text": "Formulardruck", "correct": true, "because": "Einfacher Textdruck"}, {"text": "Fotodruck", "correct": false, "because": "Nicht geeignet"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Impactdrucker verwenden Nadeln oder Typenräder. b) Sie sind für hochauflösende Grafiken geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nadeln ja, Grafiken nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Impactdrucker benötigen Farbbänder. b) Sie sind leiser als Tintenstrahldrucker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Farbbänder ja, lauter als Tintenstrahl"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Impactdrucker sind für Durchschlagpapier geeignet. b) Ihre Druckgeschwindigkeit übertrifft die von Laserdruckern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Durchschlag ja, langsamer als Laser"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Nadelmatrixdrucker sind eine Form von Impactdruckern. b) Sie eignen sich für farbigen Fotodruck.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nadelmatrix ja, Fotodruck nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Impactdrucker sind robust und langlebig. b) Sie benötigen keine speziellen Papiertypen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Robust ja, Durchschlagpapier nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

